function context(v){const selected=v.lessonTopic||v.topicChosen||v.topic||'尚未核定；請沿用原對話已確認的主題';const brief=v.topicBriefAdopted||api.context();return '【溝通Brief與確認資料】\n'+brief+'\n\n【本次已選主題】\n'+selected+'\n\n【核定的逐頁圖內文字】\n'+(v.lessonCopy||v.onImageFinal||'尚未貼回網站；若同一段AI對話已有核定文字請沿用，不自創核定內容。')+'\n\n【已完成的正文】\n'+(v.lessonPostsAdopted||v.aidaFinal||'未貼回；需要時沿用同一段AI對話已完成的正文。');}
