function refresh(v){values=v;for(const track of ['copy','image']){if(!$('cs-'+track))continue;const e=active(track);if(rendered[track]!==e.id){$('cs-task-'+track).value=e.id;draw(track);continue;}const root=$('cs-'+track);root.querySelectorAll('[data-cs-field]').forEach(el=>{let value=v[el.dataset.csField]||'';if(el.dataset.csField==='lessonTopic'&&!value)value=v.topicChosen||'';if(el.dataset.csField==='lessonCopy'&&!value)value=v.onImageFinal||'';if(el.value!==value)el.value=value;});$('cs-prompt-'+track).value=prompt(e,v);const cp=$('cs-context-'+track);if(cp)cp.textContent=context(v);const sels=e.guides.map(k=>{const cards=DATA.banks[k].filter(c=>selected(k,c.id));return names[k]+'：'+(cards.length?cards.map(c=>c.id+' '+c.name).join('＋'):'未指定，請AI建議');});$('cs-selection-'+track).textContent=sels.length?'目前選擇\n'+sels.join('\n'): '沿用前面資料，只執行目前選定任務。';root.querySelectorAll('[data-cs-use]').forEach(b=>{const [k,id]=b.dataset.csUse.split(':');const on=selected(k,id);b.setAttribute('aria-pressed',String(on));b.closest('.cs-card').classList.toggle('cs-selected',on);});}}
async function copy(text,track){try{await navigator.clipboard.writeText(text);notify('已複製。請貼到原AI對話執行。',track);}catch{notify('瀏覽器未允許複製，請選取提示詞手動複製，或下載TXT。',track);}}
function bind(){document.addEventListener('input',e=>{const el=e.target,track=el.closest('#cs-copy')?'copy':'image';if(el.dataset.csField){api.set(el.dataset.csField,el.value);return;}if(el.dataset.csSearch){const key=el.dataset.csSearch,q=el.value.trim().toLowerCase(),bank=el.closest('.cs-bank');let count=0;bank.querySelectorAll('[data-card]').forEach(c=>{c.hidden=!c.dataset.search.includes(q);if(!c.hidden)count++;});bank.querySelector('[data-cs-count]').textContent='顯示 '+count+' / '+DATA.banks[key].length+' 項';bank.querySelector('[data-cs-empty]').hidden=count!==0;}});
document.addEventListener('change',e=>{if(e.target.dataset.csTask)api.set('lessonActive'+e.target.dataset.csTask,e.target.value);});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const root=b.closest('.cs-studio'),track=root?.id==='cs-copy'?'copy':'image';if(b.dataset.csTrack){api.show(Number(b.dataset.csTrack));return;}if(!root)return;
if(b.dataset.csUse){const [k,id]=b.dataset.csUse.split(':');if(k==='light'&&Number(id.slice(1))>=7){let extra=(values.lessonLightExtra||'').split(',').filter(Boolean);if(extra.includes(id))extra=extra.filter(x=>x!==id);else{if(['L09','L10'].includes(id))extra=extra.filter(x=>!['L09','L10'].includes(x));extra.push(id);}api.set('lessonLightExtra',extra.join(','));}else if(k==='angle'&&['V09','V10','V11'].includes(id))api.set('lessonFraming',id);else api.set(lessonKey(k),id);if(k==='format'){const c=DATA.banks[k].find(c=>c.id===id);api.set('lessonSize',c.desc);}notify('已選用，下方完整提示詞已更新。',track);}
if(b.dataset.csClear){api.set(lessonKey(b.dataset.csClear),'');if(b.dataset.csClear==='format')api.set('lessonSize','');if(b.dataset.csClear==='light')api.set('lessonLightExtra','');if(b.dataset.csClear==='angle')api.set('lessonFraming','');notify('已清除此項，提示詞會請AI建議。',track);}
if(b.dataset.csCopy)copy(prompt(active(track)),track);
if(b.dataset.csDownload)api.download('我的練習_'+active(track).title+'.txt',prompt(active(track)),'text/plain;charset=utf-8');
if(b.dataset.csCopycard||b.dataset.csCopyen){const [k,id]=(b.dataset.csCopycard||b.dataset.csCopyen).split(':'),c=DATA.banks[k].find(c=>c.id===id);copy(b.dataset.csCopyen?c.en:c.name+'\n'+c.desc,track);}
if(b.dataset.csAdopt){const e=active(track),text=values['lesson_'+e.id+'_adopted']?.trim();if(!text){notify('請先填入採用的成果，再帶入下一步。',track);return;}const k=b.dataset.csAdopt==='topic'?'lessonTopic':b.dataset.csAdopt==='copy'?'lessonCopy':'lessonPostsAdopted';api.set(k,text);notify('已帶入共同設定，後續練習會沿用。',track);}});}
function labels(){const out={};shared.forEach(([k,t])=>out[lessonKey(k)]='創作共同設定｜'+t);out.lessonPostsAdopted='已完成正文';out.lessonLightExtra='燈光補充設定';out.lessonFraming='取景設定';for(const [k,t] of Object.entries(names))out[lessonKey(k)]='選用｜'+t;for(const e of DATA.exercises){for(const [k,t] of e.fields)out['lesson_'+e.id+'_'+k]=e.title+'｜'+t;out['lesson_'+e.id+'_reply']=e.title+'｜AI回覆';out['lesson_'+e.id+'_adopted']=e.title+'｜採用成果';}return out;}
function exportPrompts(v){return DATA.exercises.filter(e=>e.id===active(e.track).id||Object.keys(v).some(k=>k.startsWith('lesson_'+e.id+'_')&&v[k]?.trim())).map(e=>({stage:'課堂練習｜'+e.title+'（'+sourceLabel(e)+'）',text:prompt(e,v)}));}
