const legacy9=document.createElement('details');legacy9.className='cs-legacy';legacy9.innerHTML='<summary>先前生成與編修工具（保留）</summary>';const stage9=$('stage9');while(stage9.firstChild)legacy9.append(stage9.firstChild);stage9.append(legacy9);const note=document.createElement('p');note.className='guide';note.textContent='新版練習已整合在08：生成底圖、含字編排與多用途輸出。下方保留先前工具與草稿。';stage9.prepend(note);const nav9=document.querySelector('aside [data-stage="9"]');if(nav9){nav9.querySelector('span').textContent='09 先前編修工具';nav9.querySelector('small').textContent='保留歷史草稿；新版操作在07與08';}
